const field = document.querySelector("#field");

function setShipColor(color) {
  // --ship-color değişkenini değiştir
  document.documentElement.style.setProperty("--ship-color", color);
}

function flashHit() {
  // hit sınıfını ekle, 150 ms sonra kaldır
  field.classList.add("hit");
  setTimeout(() => {
    field.classList.remove("hit");
  }, 150);
}

// renk düğmelerini dinle
document.querySelectorAll("#colors [data-color]").forEach((btn) => {
  btn.addEventListener("click", () => setShipColor(btn.dataset.color));
});

check.js:
const shipVar = () => getComputedStyle(document.documentElement).getPropertyValue("--ship-color").trim();
click($$("#colors [data-color]")[1]);
assert(shipVar() === "#4dd0e1", "Turkuaz düğmesi --ship-color'ı '#4dd0e1' yapmalı.");
assert(getComputedStyle($("#ship")).backgroundColor === "rgb(77, 208, 225)", "Gemi turkuaza dönmeli.");
setShipColor("#ff6b6b");
assert(getComputedStyle($("#ship")).backgroundColor === "rgb(255, 107, 107)", "setShipColor('#ff6b6b') gemiyi kırmızı yapmalı.");
assert(!$("#field").classList.contains("hit"), "Başta #field'da hit sınıfı olmamalı.");
