const list = document.querySelector("#task-list");

function updateProgress() {
  // biten / toplam → #progress-text ve --progress
  const total = list.querySelectorAll("li").length;
  const done = list.querySelectorAll("li.done").length;
  const percent = total === 0 ? 0 : Math.round((done / total) * 100);
  document.querySelector("#progress").style.setProperty("--progress", percent + "%");
  document.querySelector("#progress-text").textContent = `${done} / ${total}`;
}

function addTask(text) {
  const li = document.createElement("li");
  li.textContent = text;
  // tıklanınca done sınıfını aç/kapat ve ilerlemeyi güncelle
  li.addEventListener("click", () => {
    li.classList.toggle("done");
    updateProgress();
  });
  list.append(li);
  updateProgress();
}

addTask("Matematik ödevi");
addTask("Fizik tekrarı");
addTask("İngilizce kelimeler");

check.js:
const progressVar = () => $("#progress").style.getPropertyValue("--progress").trim();
const items = () => $$("#task-list li");
assert($("#progress-text").textContent === "0 / 3", "Başta #progress-text '0 / 3' olmalı.");
click(items()[0]);
assert(items()[0].classList.contains("done"), "Göreve tıklayınca done sınıfı eklenmeli.");
assert($("#progress-text").textContent === "1 / 3" && progressVar() === "33%", "1 görev bitince '1 / 3' yazmalı ve --progress '33%' olmalı.");
const width = parseFloat(getComputedStyle($("#progress-bar")).width);
assert(width > 60 && width < 72, "İlerleme çubuğu --progress ile dolmalı (200px'in %33'ü).");
click(items()[2]);
assert($("#progress-text").textContent === "2 / 3" && progressVar() === "67%", "2 görev bitince '2 / 3' ve '67%' olmalı.");
click(items()[0]);
assert(!items()[0].classList.contains("done") && $("#progress-text").textContent === "1 / 3" && progressVar() === "33%", "Aynı göreve tekrar tıklayınca done kalkmalı ve ilerleme azalmalı.");
addTask("Kitap okuma");
assert($("#progress-text").textContent === "1 / 4" && progressVar() === "25%", "Yeni görev eklenince '1 / 4' ve '25%' olmalı.");

