project_task.solution:
const question = { text: "Ay, hangi gezegenin uydusudur?", options: ["Mars", "Dünya", "Jüpiter"], correct: 1 };
const buttons = document.querySelectorAll(".option");
const feedback = document.querySelector("#feedback");
let score = 0;
let answered = false;

function answer(index) {
  if (answered) return;
  answered = true;
  // doğru düğmeye correct, yanlış seçilene wrong
  buttons[question.correct].classList.add("correct");
  if (index === question.correct) {
    score += 10;
    document.querySelector("#score").textContent = score;
    feedback.textContent = "Doğru!";
  } else {
    buttons[index].classList.add("wrong");
    feedback.textContent = `Yanlış! Doğru cevap: ${question.options[question.correct]}`;
  }
}

function resetOptions() {
  // sınıfları kaldır, answered = false, #feedback boş
  buttons.forEach((btn) => btn.classList.remove("correct", "wrong"));
  answered = false;
  feedback.textContent = "";
}

buttons.forEach((btn, i) => btn.addEventListener("click", () => answer(i)));

check.js:
const b = $$(".option");
const cls = () => b.map((x) => (x.classList.contains("correct") ? "c" : "") + (x.classList.contains("wrong") ? "w" : "") || "-").join(",");
answer(0);
assert(cls() === "w,c,-", "Mars'ı (0) seçince Mars wrong, Dünya correct olmalı; Jüpiter'e dokunulmamalı.");
assert(getComputedStyle(b[1]).backgroundColor === "rgb(46, 125, 50)" && getComputedStyle(b[0]).backgroundColor === "rgb(198, 40, 40)", "Doğru seçenek yeşil, yanlış seçilen kırmızı görünmeli (CSS hazır).");
resetOptions();
assert(cls() === "-,-,-" && answered === false && $("#feedback").textContent === "", "resetOptions() sınıfları kaldırmalı, answered'ı false yapmalı ve #feedback'i boşaltmalı.");
answer(1);
assert(cls() === "-,c,-", "Doğru cevapta yalnızca doğru düğme correct olmalı, wrong olmamalı.");
resetOptions();
question.correct = 2;
answer(0);
assert(cls() === "w,-,c", "Doğru düğme question.correct'ten bulunmalı (elle 1 yazma).");
